// Station 1.2: Das Wartezimmer der Praxis und der Taxistand am Bahnhof
// sollen dieselbe Klasse Warteschlange benutzen.

Warteschlange praxis = new Warteschlange();
praxis.add(new Patient("Resi", "Grippe"));
praxis.add(new Patient("Bene", "Kopfweh"));
println("--- Wartezimmer ---");
praxis.ausgeben();

Warteschlange taxistand = new Warteschlange();
taxistand.add(new Taxi(12, "Stefan"));
taxistand.add(new Taxi(7, "Aylin"));
taxistand.add(new Taxi(3, "Jonas"));
println("--- Taxistand ---");
taxistand.ausgeben();
println("Fahrgast steigt ein bei: " + taxistand.poll().gibSchluesselwert());

/**
 * Der Vertrag für alles, was in einer Warteschlange stehen darf.
 * Ein Interface enthält nur Methodenköpfe, keine Rümpfe.
 */
public interface DatenElement {
   String gibSchluesselwert();   // z. B. der Name oder die Taxinummer
}

/**
 * Die Daten einer Patientin oder eines Patienten (aus Station 1.1).
 */
public class Patient implements DatenElement {
   private String name;
   private String beschwerden;

   public Patient(String name, String beschwerden) {
      this.name = name;
      this.beschwerden = beschwerden;
   }

   public String getName() {
      return name;
   }

   public String getBeschwerden() {
      return beschwerden;
   }

   // Methode aus dem Vertrag DatenElement
   public String gibSchluesselwert() {
      return name;
   }
}

/**
 * Ein Taxi am Taxistand.
 */
public class Taxi implements DatenElement {
   private int nummer;
   private String fahrer;

   public Taxi(int nummer, String fahrer) {
      this.nummer = nummer;
      this.fahrer = fahrer;
   }

   public int getNummer() {
      return nummer;
   }

   public String getFahrer() {
      return fahrer;
   }

   // Methode aus dem Vertrag DatenElement
   public String gibSchluesselwert() {
      return "Taxi " + nummer;
   }
}

/**
 * Ein Knoten der Warteschlange: trägt ein beliebiges DatenElement.
 */
public class Knoten {
   private DatenElement daten;
   private Knoten nachfolger;

   public Knoten(DatenElement daten) {
      this.daten = daten;
      nachfolger = null;
   }

   public DatenElement getDaten() {
      return daten;
   }

   public Knoten getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }
}

/**
 * Warteschlange (Queue) für beliebige DatenElemente.
 */
public class Warteschlange {
   private Knoten anfang;   // erster Knoten: kommt als Nächstes dran
   private Knoten ende;     // letzter Knoten: hier wird angehängt

   public Warteschlange() {
      anfang = null;
      ende = null;
   }

   public boolean isEmpty() {
      return anfang == null;
   }

   public boolean add(DatenElement daten) {
      Knoten neu = new Knoten(daten);
      if (isEmpty()) {
         anfang = neu;
         ende = neu;
      } else {
         ende.setNachfolger(neu);
         ende = neu;
      }
      return true;
   }

   public DatenElement poll() {
      if (isEmpty()) {
         return null;
      } else {
         DatenElement daten = anfang.getDaten();
         anfang = anfang.getNachfolger();
         if (anfang == null) {
            ende = null;
         }
         return daten;
      }
   }

   public DatenElement peek() {
      if (isEmpty()) {
         return null;
      } else {
         return anfang.getDaten();
      }
   }

   public void ausgeben() {
      Knoten aktuell = anfang;
      int platz = 1;
      while (aktuell != null) {
         println("  " + platz + ". " + aktuell.getDaten().gibSchluesselwert());
         aktuell = aktuell.getNachfolger();
         platz++;
      }
   }
}
